head.script:
scwin.screenId = "jldstf07091";

///////// 1. 변수 및 선언 영역 /////////


scwin.vBzProcsNo = "";

scwin.vListInvstgBzTpCd = "";

scwin.clickListBzDtlTpCd = "";

scwin.clickAdjReqProcsNo = "";

scwin.vScrenID = "ULDSTF07091.gfm";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.vScrenProcTpCd = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const parentWin = $c.frame.Provider("../");
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vListInvstgBzTpCd = parentWin.clickListInvstgBzTpCd;
        await scwin.listSync();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07091.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');

scwin.pMenuID = undefined; try { scwin.pMenuID = /* sdd-asis-lifecycle:begin pMenuID — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.win.getProgramId()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07091' }); }

scwin.fr_MktId = undefined; try { scwin.fr_MktId = /* sdd-asis-lifecycle:begin fr_MktId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.lc.fn_getMktId()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07091' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07091.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_List_ondblclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param row colid
 * @returns
 * @hidden N
*/
scwin.grd_List_ondblclick = async function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin grd_List_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.setBzProcsNo(row);
        if ("FUNC_ACPT" === colid) {
            var vAnswer = await $c.win.confirm('승인처리 하시겠습니까?');
            if (vAnswer === true) {
                LastJob = "승인";
                scwin.fn_trs("35");
            }
        } else {
            if ("FUNC_RJCT" === colid) {
                var vAnswer = await $c.win.confirm('불가처리 하시겠습니까?');
                if (vAnswer === true) {
                    LastJob = "불가";
                    scwin.fn_trs("36");
                }
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07091.grd_List_ondblclick' }); }
};

/**
 * @method
 * @name scwin.dts_List_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_List_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_List_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    void 0;
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.dts_List_onloaderror
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dts_List_onloaderror = function () {
    /* sdd-asis-lifecycle:begin dts_List_onloaderror — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.alert_error(scwin.dts_List);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onfail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onfail = function () {
    /* sdd-asis-lifecycle:begin trs_Save_onfail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.lc.fn_alertMsg('F');
    $c.fil.alert_error(trs_Save);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onsuccess = async function () {
    /* sdd-asis-lifecycle:begin trs_Save_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.lc.fn_alertMsg('S');
    await scwin.listSync();
    scwin.parentRefresh();
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07091.btn_Close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_List
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_List = async function () {
    $c.util.getComponent("dma_scriptDts_ListReq").set("SCREN_ID", "ULDSTF07091.gfm");
    $c.util.getComponent("dma_scriptDts_ListReq").set("BZ_PROCS_NO", "");
    $c.util.getComponent("dma_scriptDts_ListReq").set("LIST_INVSTG_BZ_TP_CD", "");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/konex/LstInvstgKonexCommon.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07091.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.sbm_trs_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/konex/LstInvstgKonexCommon.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07091.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.listSync = async function () {
    /* sdd-asis-lifecycle:begin fn_list_sync — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let url = "/konex/LstInvstgKonexCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=listAdjReq";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&LIST_INVSTG_BZ_TP_CD=" + scwin.vListInvstgBzTpCd;

    await scwin.tx_script_dts_List();
    void 0;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setBzProcsNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.setBzProcsNo = function (obj) {
    /* sdd-asis-lifecycle:begin setBzProcsNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.clickListBzDtlTpCd = scwin.dts_List.getCellData((obj), "LIST_BZ_DTL_TP_CD");
    scwin.clickAdjReqProcsNo = scwin.dts_List.getCellData((obj), "ADJ_REQ_PROCS_NO");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.parentRefresh
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.parentRefresh = function () {
    /* sdd-asis-lifecycle:begin fn_parentRefresh — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fr_fn_list_sync = $c.frame.Provider("../").fn_list_sync;
    fr_fn_list_sync();
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_trs = scwin.sbm_trs_Save;
